import React, { useState, useEffect } from 'react';
import axios from 'axios';

export default function StudentTimetable({ studentGrade = 'Grade 8' }) {
  const [timetableData, setTimetableData] = useState([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    axios.get('http://localhost:8082/api/timetable')
      .then(res => {
        // ශිෂ්‍යයාගේ Grade එකට අදාළ Classes විතරක් Filter කිරීම
        const filtered = res.data.filter(
          item => item.grade.toString().trim().toLowerCase() === studentGrade.toString().trim().toLowerCase()
        );
        setTimetableData(filtered);
        setLoading(false);
      })
      .catch(err => {
        console.error("Error fetching timetable:", err);
        setLoading(false);
      });
  }, [studentGrade]);

  const days = ['Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday', 'Sunday'];

  if (loading) {
    return <div style={{ padding: '20px', color: '#64748b' }}>Loading timetable...</div>;
  }

  return (
    <div style={styles.card}>
      <h3 style={styles.title}>
        📅 Live Weekly Class Timetable ({studentGrade})
      </h3>

      {timetableData.length === 0 ? (
        <div style={{ textAlign: 'center', padding: '40px 20px', color: '#64748b', backgroundColor: '#f8fafc', borderRadius: '8px' }}>
          🚫 No classes scheduled for {studentGrade} yet.
        </div>
      ) : (
        <div style={{ overflowX: 'auto' }}>
          <table style={styles.table}>
            <thead>
              <tr>
                <th style={styles.th}>Day</th>
                <th style={styles.th}>Time Slot</th>
                <th style={styles.th}>Subject</th>
                <th style={styles.th}>Teacher</th>
              </tr>
            </thead>
            <tbody>
              {timetableData.map((item, index) => (
                <tr key={index} style={styles.tr}>
                  <td style={{ ...styles.td, fontWeight: 'bold', color: '#1e293b' }}>{item.day}</td>
                  <td style={{ ...styles.td, color: '#0284c7', fontWeight: '600' }}>{item.time_slot}</td>
                  <td style={{ ...styles.td, fontWeight: 'bold', color: '#15803d' }}>{item.subject}</td>
                  <td style={{ ...styles.td, color: '#475569' }}>{item.teacher}</td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      )}
    </div>
  );
}

const styles = {
  card: { backgroundColor: '#ffffff', borderRadius: '12px', padding: '24px', boxShadow: '0 4px 20px rgba(0, 0, 0, 0.03)', margin: '20px' },
  title: { margin: '0 0 20px 0', color: '#1e293b', fontSize: '18px', fontWeight: '700' },
  table: { width: '100%', borderCollapse: 'collapse', fontSize: '14px', textAlign: 'left' },
  th: { backgroundColor: '#f8fafc', color: '#64748b', fontWeight: '600', padding: '12px 15px', borderBottom: '2px solid #e2e8f0' },
  tr: { borderBottom: '1px solid #f1f5f9' },
  td: { padding: '14px 15px', verticalAlign: 'middle' }
};
